import React, { type ReactNode } from 'react';
import styled from 'styled-components';
import { Table } from '@mendix/ide-ui-components/table/table/Table';
import { TableHead } from '@mendix/ide-ui-components/table/table/TableHead';
import { TableHeader } from '@mendix/ide-ui-components/table/table/TableHeader';
import { TableBody } from '@mendix/ide-ui-components/table/table/TableBody';
import { TableRow } from '@mendix/ide-ui-components/table/table/TableRow';
import { TableCell } from '@mendix/ide-ui-components/table/table/TableCell';
import { ContentWrapper } from '@mendix/ide-ui-components/table/table/ContentWrapper';
import { Toolbar, LeftItems, RightItems } from '@mendix/ide-ui-components/toolbar/Toolbar';
import type { Selection } from '@mendix/ide-ui-components/table/Table';

const TransparentToolbar = styled(Toolbar)`
    background-color: transparent;
    & button {
        background-color: transparent;
    }
`;

const TableContainer = styled.div`
    display: flex;
    flex-direction: column;
`;

const StyledTableHeader = styled(TableHeader)`
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
`;

const StyledTableCell = styled(TableCell)`
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
`;

const StyledTable = styled(Table)`
    border-bottom: none;
    height: unset;
    min-height: unset;
`;

interface TableColumn {
    id: string;
    caption: string;
    isRowHeader?: boolean;
    useContentWrapper?: boolean;
    contentTitle?: string;
}

interface TableComponentProps {
    ariaLabel: string;
    columns: TableColumn[];
    data: (string | ReactNode)[][];
    stickyHeader?: boolean;
    emptyMessage?: string;
    toolbarLeft?: ReactNode;
    toolbarRight?: ReactNode;
    selectionType?: "column" | "row" | "none";
    selectionMode?: "none" | "single";
    selectedKeys?: Selection;
    onSelectionChange?: (selection: Selection) => void;
}

const TableComponent: React.FC<TableComponentProps> = ({
    ariaLabel,
    columns,
    data,
    stickyHeader = false,
    emptyMessage = "No data available.",
    toolbarLeft,
    toolbarRight,
    selectionType,
    selectionMode = "single",
    selectedKeys,
    onSelectionChange,
}) => {
    return (
        <TableContainer>
            {(toolbarLeft || toolbarRight) && (
                <TransparentToolbar aria-label={`${ariaLabel} toolbar`}>
                    {toolbarLeft && <LeftItems>{toolbarLeft}</LeftItems>}
                    {toolbarRight && <RightItems>{toolbarRight}</RightItems>}
                </TransparentToolbar>
            )}
            <StyledTable
                aria-label={ariaLabel}
                stickyHeader={stickyHeader}
                selectionType={selectionType}
                selectionMode={selectionMode}
                selectedKeys={selectedKeys}
                onSelectionChange={onSelectionChange}
            >
                <TableHead>
                    {columns.map(column => (
                        <StyledTableHeader
                            key={column.id}
                            id={column.id}
                            isRowHeader={column.isRowHeader}
                        >
                            {column.caption}
                        </StyledTableHeader>
                    ))}
                </TableHead>
                <TableBody>
                    {data.length === 0 ? (
                        <TableRow>
                            <StyledTableCell columnId={columns[0]?.id}>
                                {emptyMessage}
                            </StyledTableCell>
                            {columns.slice(1).map(column => (
                                <StyledTableCell key={column.id} columnId={column.id}>
                                    {/* Empty cell */}
                                </StyledTableCell>
                            ))}
                        </TableRow>
                    ) : (
                        data.map((row, rowIndex) => (
                            <TableRow
                                key={rowIndex}
                                id={String(rowIndex)}>
                                {row.map((cellData, cellIndex) => {
                                    const column = columns[cellIndex];
                                    const content = column?.useContentWrapper ? (
                                        <ContentWrapper title={column.contentTitle}>
                                            {cellData}
                                        </ContentWrapper>
                                    ) : cellData;

                                    return (
                                        <StyledTableCell key={cellIndex} columnId={column.id}>
                                            {content}
                                        </StyledTableCell>
                                    );
                                })}
                            </TableRow>
                        ))
                    )}
                </TableBody>
            </StyledTable>
        </TableContainer>
    );
};

export default TableComponent;