export const handleValidateAgent = async (field: keyof Agent, studioPro: StudioProApi, agent: Agent): Promise<true | string> => {
    switch (field) {
        case "modelQualifiedName":
            if (!agent.modelQualifiedName) {
                return "Please select a model.";
            }
            const modelDocuments: DocumentsOfTypeResult = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId);
            const matchOfCorrectType = modelDocuments.find(d => d.moduleName + '.' + d.name === agent.modelQualifiedName);
            if (!matchOfCorrectType) {
                return "This document is invalid. Make sure to select a document of type Model."
            }
            break;

        case "entity":
            if (agent.variables.length > 0 && !agent.entity) {
                return "Please select an entity.";
            }
            const [moduleName, entityDocument] = agent.entity.split('.');
            if (agent.entity && (!moduleName || !entityDocument)) {
                return "The selected entity is not valid."
            }
            const isEntityFound = await isAgentEntityFound(studioPro, agent);
            if (!isEntityFound) {
                return "Entity no longer exists."
            }
            break;

        case "userPrompt":
            if (!agent.userPrompt) {
                return "Please provide a user prompt.";
            }
            break;

        default:
            return true;
    }
    return true;
}


export const handleShowModel = async (studioPro: StudioProApi, modelQualifiedName: string): Promise<void> => {
    if (!modelQualifiedName) {
        return;
    }
    const model = (await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId)).find(d => d.moduleName + '.' + d.name === modelQualifiedName);
    if (!model) {
        const errorMessage = "Could not find model.";
        const errorDetails = "This model might have been deleted or renamed. Please update the model selection.";
        studioPro.ui.messageBoxes.show(
            "error",
            errorMessage,
            errorDetails
        );
        return;
    }
    studioPro.ui.editors.editDocument(model.id);
};


export const handleEditModelSettings = async (studioPro: StudioProApi, componentName: string, agent: Agent, updateAgentDocument: (agent: Agent) => Promise<void>): Promise<Agent | undefined> => {
    const result = await studioPro.ui.dialogs.showModal(
        {
            title: "Model settings",
            contentSize: { height: 385, width: 600 }
        },
        {
            componentName: componentName,
            uiEntrypoint: "modelSettingsEdit",
            queryParams: {
                agent: encodeURIComponent(JSON.stringify(agent))
            }
        }
    );
    let updatedAgent: Agent | undefined = undefined;
    if (result) {
        updatedAgent = result as Agent;
    }
    if (updatedAgent) {
        updateAgentDocument(updatedAgent);
    }
    return updatedAgent;
};

export const handleEditTool = async (studioPro: StudioProApi, componentName: string, agent: Agent, updateAgentDocument: (agent: Agent) => Promise<void>, toolIndex?: number): Promise<Agent | null> => {
    const tool = (toolIndex !== undefined && agent.tools) ? agent.tools[toolIndex] : undefined;

    const result = await studioPro.ui.dialogs.showModal(
        {
            title: tool ? "Edit tool" : "Add tool",
            contentSize: { height: 330, width: 600 },
        },
        {
            componentName: componentName,
            uiEntrypoint: "toolEdit",
            queryParams: {
                tool: tool ? encodeURIComponent(JSON.stringify(tool)) : ""
            }
        }
    );

    if (result !== null) {
        const newTool = result as Tool;
        let updatedTools: Tool[];

        if (toolIndex !== undefined && agent.tools) {
            // Edit mode: replace the tool at the specified index
            updatedTools = [...agent.tools];
            updatedTools[toolIndex] = newTool;
        } else {
            // Add mode: add new tool
            updatedTools = [...(agent.tools || []), newTool];
        }

        // Always keep tools sorted by name
        updatedTools.sort((a, b) => a.name.localeCompare(b.name));

        const updatedAgent = { ...agent, tools: updatedTools };
        updateAgentDocument(updatedAgent);
        return updatedAgent;
    } else {
        return null;
    }
};

export const handleDeleteTool = async (studioPro: StudioProApi, agent: Agent, updateAgentDocument: (agent: Agent) => Promise<void>, toolIndex: number): Promise<Agent> => {
    const updatedTools = agent.tools.filter((_tool, index) => index !== toolIndex);
    const updatedAgent = { ...agent, tools: updatedTools };
    updateAgentDocument(updatedAgent);
    return updatedAgent;
}